#!/usr/bin/env python3
import sys


def read_variants(path, limit):
    variants = []
    with open(path, "rt", encoding="utf-8") as handle:
        for line in handle:
            if not line or line.startswith("#"):
                continue
            fields = line.rstrip("\n").split("\t")
            if len(fields) < 5:
                raise ValueError("VCF record has fewer than five columns")
            chrom, pos, ref, alt = fields[0], int(fields[1]), fields[3].upper(), fields[4].upper()
            if chrom not in ("20", "chr20"):
                raise ValueError(f"Unexpected chromosome: {chrom}")
            if len(ref) != 1 or len(alt) != 1 or ref not in "ACGT" or alt not in "ACGT":
                raise ValueError(f"Non-biallelic-SNP record at {chrom}:{pos}")
            variants.append((pos, ref))
            if limit and len(variants) >= limit:
                break
    return variants


